\cup
\{
\bigl(\operatorname{tc}(\vec x,\vec y,\varphi,\vec s,\vec t),
\operatorname{tc}(\vec x',\vec y',
\operatorname{SubVec}_{TC}(\operatorname{SubVec}_{TC}(\varphi,\vec x,\vec x'),\vec y,\vec y'),
\vec s,\vec t)\bigr):
\exists n\in\mathbb N\,
(\vec x,\vec y,\vec x',\vec y':n\to\mathsf{Var}
\land \vec x,\vec y,\vec x',\vec y'\text{ 均为单射}
\land \operatorname{rng}(\vec x)\cap\operatorname{rng}(\vec y)=\varnothing
\land \operatorname{rng}(\vec x')\cap\operatorname{rng}(\vec y')=\varnothing
\land \vec s,\vec t:n\to\mathsf{Tm}_{TC}^{\Sigma}
\land \varphi\in\mathsf{Fm}_{TC}^{\Sigma}
\land
\operatorname{rng}(\vec x')\cup\operatorname{rng}(\vec y')
\text{ 避开 }
\operatorname{FV}(\varphi)\setminus(\operatorname{rng}(\vec x)\cup\operatorname{rng}(\vec y)))
\}.
